import type { ReactNode } from "react";

export const dataGridDensityValues = ["compact", "standard", "comfortable"] as const;
export const dataGridSelectionModeValues = ["none", "single", "multiple"] as const;

/** Accessible, virtualized data grid for large datasets: sorting, filtering, row selection, resizable and pinned columns, row grouping with totals, tree data and expandable detail rows. Columns are TanStack Table column definitions. */
export interface DataGridSpecProps {
  /**
   * Accessible name of the grid, e.g. 'Orders'.
   */
  label: string;
  /**
   * Rows to show. Keep the array reference stable between renders.
   */
