   * Stable id per row. Needed for selection to survive sorting and filtering.
   */
  getRowId?: (row: any, index: number) => string;
  /**
   * Row height: 32, 40 or 48px.
   * @default "standard"
   */
  density?: "compact" | "standard" | "comfortable";
  /**
   * Height of the scrolling area in px.
   * @default 480
   */
  height?: number;
  /**
   * Renders only visible rows. Keeps 100k rows fast.
   * @default true
   */
  virtualized?: boolean;
  /**
   * Lets users sort by clicking or pressing Enter on a header. Shift adds a secondary sort.
   * @default true
   */
  sortable?: boolean;
  /**
   * Adds a checkbox column and Space-to-select.
   * @default "none"
   */
  selectionMode?: "none" | "single" | "multiple";
  /**
   * Controlled selection, by row id.
   */
  selectedRowIds?: readonly string[];
  /**
   * Initial selection when uncontrolled.
   */
  defaultSelectedRowIds?: readonly string[];
  /**
   * Called with the selected row ids.
   */
  onSelectionChange?: (ids: string[]) => void;
  /**
   * Shows only rows where some cell contains this text (case-insensitive).
   */
  globalFilter?: string;
  /**
   * Drag a header edge, or press Alt+Left/Right on a header, to resize.
   * @default true
   */
  resizableColumns?: boolean;
  /**
   * Column ids kept visible on the left while scrolling sideways.
   */
  pinnedColumns?: readonly string[];
  /**
   * Adds a filter row under the header. Set meta.filter on a column to 'text', 'select' or false.
   * @default false
   */
  showColumnFilters?: boolean;
  /**
   * Rows per page. When set, a pager is shown; when not, all rows scroll (virtualized).
   */
  pageSize?: number;
