   * Called when the user saves an edit in a column with meta.editable. Update your data to apply it.
   */
  onCellEdit?: (edit: import("../data-grid/types").DataGridCellEdit<any>) => void;
  /**
   * Marks the grid busy and shows a loading message.
   * @default false
