  groupBy?: readonly string[];
  /**
   * Start with every group, tree row and detail panel open.
   * @default false
   */
  defaultExpanded?: boolean;
  /**
   * Tree data: returns a row's children. Rows with children get an expand toggle and are indented by depth. Search keeps a parent when a child matches.
   */
  getSubRows?: (row: any) => readonly any[] | undefined;
  /**
   * Master-detail: content shown in a panel under a row when it's expanded.
   */
  renderDetail?: (row: any) => import("react").ReactNode;
  /**
