  detailHeight?: number;
}

export const dataGridDefaults = {
  density: "standard",
  height: 480,
  virtualized: true,
  sortable: true,
  selectionMode: "none",
  resizableColumns: true,
  showColumnFilters: false,
  isLoading: false,
  emptyMessage: "No rows",
