import { createContext, forwardRef, useContext } from "react";
import {
  Tab as AriaTab,
  TabList as AriaTabList,
  TabPanel as AriaTabPanel,
  Tabs as AriaTabs,
  type TabListProps as AriaTabListProps,
  type TabPanelProps as AriaTabPanelProps,
  type TabProps as AriaTabProps,
  type TabsProps as AriaTabsProps,
} from "react-aria-components";
import { tabsDefaults, type TabsSpecProps } from "../generated/tabs.types";
import { cx } from "../utils/cx";

type Variant = NonNullable<TabsSpecProps["variant"]>;

// Tab and TabList read the variant from here, so it's set once on <Tabs>.
const VariantContext = createContext<Variant>(tabsDefaults.variant);

export interface TabsProps
  extends TabsSpecProps,
    Omit<AriaTabsProps, keyof TabsSpecProps | "className" | "children"> {
  className?: string;
}

export const Tabs = forwardRef<HTMLDivElement, TabsProps>(function Tabs(
  {
    variant = tabsDefaults.variant,
    orientation = tabsDefaults.orientation,
    isDisabled = tabsDefaults.isDisabled,
    children,
    className,
    ...rest
  },
  ref,
) {
  return (
    <VariantContext.Provider value={variant}>
      <AriaTabs
        {...rest}
        ref={ref}
        orientation={orientation}
        isDisabled={isDisabled}
        className={cx("flex gap-4 data-[orientation=horizontal]:flex-col", className)}
      >
        {children}
      </AriaTabs>
    </VariantContext.Provider>
  );
});

const listStyles: Record<Variant, string> = {
  underline:
    "border-[var(--rd-color-border-default)] data-[orientation=horizontal]:border-b data-[orientation=vertical]:border-r",
  pill: "rounded-[var(--rd-radius-control)] bg-[var(--rd-color-surface-subtle)] p-1",
};

export interface TabListProps<T extends object> extends Omit<AriaTabListProps<T>, "className"> {
  className?: string;
}

export function TabList<T extends object>({ className, ...rest }: TabListProps<T>) {
  const variant = useContext(VariantContext);
  return (
    <AriaTabList
      {...rest}
      className={cx("flex gap-1 data-[orientation=vertical]:flex-col", listStyles[variant], className)}
    />
  );
}

const tabStyles: Record<Variant, string> = {
  underline:
    "-mb-px border-b-2 border-transparent px-3 py-2 " +
    "data-[selected]:border-[var(--rd-color-action-primary)] data-[selected]:text-[var(--rd-color-text-default)]",
  pill:
    "rounded-[calc(var(--rd-radius-control)-2px)] px-3 py-1.5 " +
    "data-[selected]:bg-[var(--rd-color-surface-raised)] data-[selected]:text-[var(--rd-color-text-default)] data-[selected]:shadow-sm",
};

export interface TabProps extends Omit<AriaTabProps, "className"> {
  className?: string;
}

export function Tab({ className, ...rest }: TabProps) {
  const variant = useContext(VariantContext);
  return (
    <AriaTab
      {...rest}
      className={cx(
        "cursor-default text-sm font-medium outline-none transition-colors text-[var(--rd-color-text-muted)] " +
          "data-[hovered]:text-[var(--rd-color-text-default)] " +
          "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)] " +
          "data-[disabled]:opacity-50",
        tabStyles[variant],
        className,
      )}
    />
  );
}

export interface TabPanelProps extends Omit<AriaTabPanelProps, "className"> {
  className?: string;
}

export function TabPanel({ className, ...rest }: TabPanelProps) {
  return (
    <AriaTabPanel
      {...rest}
      className={cx(
        "flex-1 outline-none text-[var(--rd-color-text-default)] " +
          "data-[focus-visible]:ring-2 data-[focus-visible]:ring-[var(--rd-color-focus-ring)] rounded-[var(--rd-radius-control)]",
        className,
      )}
    />
  );
}

// Generated by rdloom codegen from specs/tabs.spec.json (v0.1.0).
// Do not edit. Change the spec and run `npm run gen`.

import type { ReactNode } from "react";

export const tabsVariantValues = ["underline", "pill"] as const;
export const tabsOrientationValues = ["horizontal", "vertical"] as const;

/** Switches between related panels of content in the same place. Use with TabList, Tab and TabPanel. */
export interface TabsSpecProps {
  /**
   * Visual style of the tab list.
   * @default "underline"
   */
  variant?: "underline" | "pill";
  /**
   * Direction of the tab list.
   * @default "horizontal"
   */
  orientation?: "horizontal" | "vertical";
  /**
   * Controlled selected tab.
   */
  selectedKey?: import("react-aria-components").Key;
  /**
   * Initial tab when uncontrolled.
   */
  defaultSelectedKey?: import("react-aria-components").Key;
  /**
   * Disables every tab.
   * @default false
   */
  isDisabled?: boolean;
  /**
   * A TabList followed by TabPanels.
   */
  children: ReactNode;
  /**
   * Called with the newly selected tab key.
   */
  onSelectionChange?: (key: import("react-aria-components").Key) => void;
}

export const tabsDefaults = {
  variant: "underline",
  orientation: "horizontal",
  isDisabled: false,
} as const;

export const tabsMeta = {
  "name": "Tabs",
  "version": "0.1.0",
  "status": "experimental",
  "role": "tablist"
} as const;

